insert into public.data_catalog (id, call_id, name, source_path, metadata)
select s.id, c.id, s.name, '/cbi/data/innterconecta-step/' || s.file, s.metadata::jsonb
from public.calls c cross join (values
  ('step-proyectos', 'proyectos.csv', 'INNTERCONECTA · Proyectos concedidos', '{"group": "innterconecta-step", "role": "activo", "connection": "csv", "delimiter": ",", "headers": ["id_proyecto", "anio_convocatoria", "anio_resolucion", "programa", "expediente", "titulo", "acronimo", "representante", "puntos", "resultado", "presupuesto_elegible_eur", "subvencion_eur", "ccaa_convocatoria", "ccaa_consorcio_cdti", "num_ccaa_identificadas", "num_socios_identificados", "num_socios_con_ccaa", "estado_cobertura_ccaa", "fuente_url", "fuente_presupuesto_url", "fuente_ccaa_proyecto_url", "notas_cruce"], "numeric": ["anio_convocatoria", "anio_resolucion", "puntos", "presupuesto_elegible_eur", "subvencion_eur", "num_ccaa_identificadas", "num_socios_identificados", "num_socios_con_ccaa"], "categories": ["programa", "anio_convocatoria", "resultado", "ccaa_convocatoria"], "sourceFields": ["fuente_url", "fuente_presupuesto_url", "fuente_ccaa_proyecto_url"], "rowCount": 545, "validation": "generic", "pages": ["innterconecta-step-dashboard.html"], "description": "Concesiones consolidadas de 2011 a 2025. Una fila por proyecto.", "readme": "/cbi/data/innterconecta-step/LEEME.md"}'),
  ('step-cobertura', 'cobertura.csv', 'INNTERCONECTA · Cobertura y fuentes', '{"group": "innterconecta-step", "role": "activo", "connection": "csv", "delimiter": ",", "headers": ["anio_convocatoria", "programa", "ccaa_convocatoria", "proyectos_concedidos", "proyectos_con_ccaa_cdti", "proyectos_con_varias_ccaa_cdti", "entidades_identificadas", "entidades_con_ccaa_cdti", "subvencion_eur", "estado", "fuente_url"], "numeric": ["anio_convocatoria", "proyectos_concedidos", "proyectos_con_ccaa_cdti", "proyectos_con_varias_ccaa_cdti", "entidades_identificadas", "entidades_con_ccaa_cdti", "subvencion_eur"], "categories": ["programa", "anio_convocatoria", "ccaa_convocatoria", "estado"], "sourceFields": ["fuente_url"], "rowCount": 10, "validation": "generic", "pages": ["innterconecta-step-dashboard.html"], "description": "Cobertura histórica, regional y territorial por edición.", "readme": "/cbi/data/innterconecta-step/LEEME.md"}'),
  ('step-socios', 'socios.csv', 'INNTERCONECTA · Entidades por proyecto', '{"group": "innterconecta-step", "role": "activo", "connection": "csv", "delimiter": ",", "headers": ["anio_convocatoria", "id_proyecto", "entidad", "rol", "cif_entidad", "presupuesto_elegible_eur", "subvencion_eur", "ccaa_cdti", "provincia_cdti", "localidad_cdti", "pyme", "sector_cdti", "cnae_cdti", "fecha_registro_cdti", "fuente_territorial_url", "fuente_url"], "numeric": ["anio_convocatoria", "presupuesto_elegible_eur", "subvencion_eur"], "categories": ["rol", "ccaa_cdti", "pyme", "sector_cdti"], "sourceFields": ["fuente_territorial_url", "fuente_url"], "rowCount": 1547, "validation": "generic", "pages": ["innterconecta-step-dashboard.html"], "description": "Detalle de participantes identificados. Los importes agregados del proyecto se consultan en Proyectos concedidos.", "readme": "/cbi/data/innterconecta-step/LEEME.md"}'),
  ('step-pares-ccaa', 'pares_ccaa.csv', 'INNTERCONECTA · Colaboración entre CCAA', '{"group": "innterconecta-step", "role": "activo", "connection": "csv", "delimiter": ",", "headers": ["id_proyecto", "anio_convocatoria", "programa", "ccaa_1", "ccaa_2", "estado_cobertura_ccaa", "fuente_url"], "numeric": ["anio_convocatoria"], "categories": ["programa", "ccaa_1", "ccaa_2"], "sourceFields": ["fuente_url"], "rowCount": 362, "validation": "generic", "pages": ["innterconecta-step-dashboard.html"], "description": "Una fila por cada par de CCAA que coincide en un proyecto.", "readme": "/cbi/data/innterconecta-step/LEEME.md"}'),
  ('step-resultados-2025', 'resultados_step_2025.csv', 'INNTERCONECTA · Resultados STEP 2025', '{"group": "innterconecta-step", "role": "activo", "connection": "csv", "delimiter": ",", "headers": ["expediente", "titulo", "representante", "resultado", "puntos", "motivo", "subvencion_concedida_eur", "fuente_url"], "numeric": ["puntos", "subvencion_concedida_eur"], "categories": ["resultado"], "sourceFields": ["fuente_url"], "rowCount": 267, "validation": "generic", "pages": ["innterconecta-step-dashboard.html"], "description": "Resolución definitiva STEP 2025. Base observada de la simulación de concurrencia.", "readme": "/cbi/data/innterconecta-step/LEEME.md"}'),
  ('step-escenario-2027', 'escenario_2027.csv', 'INNTERCONECTA · Escenario 2027', '{"group": "innterconecta-step", "role": "activo", "connection": "csv", "delimiter": ",", "headers": ["id", "ejercicio", "credito_eur", "solicitudes_previstas", "estado", "notas"], "numeric": ["ejercicio", "credito_eur", "solicitudes_previstas"], "categories": ["estado"], "sourceFields": [], "rowCount": 1, "validation": "generic", "pages": ["innterconecta-step-dashboard.html"], "description": "Supuestos editables de crédito y número de expedientes evaluados.", "readme": "/cbi/data/innterconecta-step/LEEME.md"}')
) as s(id, file, name, metadata)
where c.code = 'INNTERCONECTA-STEP'
on conflict (id) do update
set name = excluded.name, source_path = excluded.source_path, metadata = excluded.metadata
where public.data_catalog.call_id = excluded.call_id;
